/* Extensão do diálogo existente: calendário cadastrado, equipes e réplica revisável. */
(()=>{'use strict';const P=MartinsPlanejamento,J=MartinsJornada,$=id=>document.getElementById(id),panel=document.createElement('details');panel.id='mp-panel';panel.innerHTML=`<summary>Planejamento por período, equipes e réplica de frequência</summary><p>Equipes e indisponibilidades são de planejamento. Só a confirmação explícita registra presenças realizadas.</p><label>Visualização<select id="mp-period"><option value="dia">Dia</option><option value="semana">Semana (segunda a domingo)</option><option value="mes">Mês</option></select></label><button id="mp-view" type="button">Atualizar período</button><div style="overflow:auto"><table><thead><tr><th>Selecionar dia</th><th>Data</th><th>Calendário cadastrado</th><th>Funcionários</th><th>Horas previstas</th><th>Abrir dia</th></tr></thead><tbody id="mp-period-rows"></tbody></table></div><h3>Equipes próprias e terceirizadas</h3><label>Nome da equipe<input id="mp-team-name" maxlength="100"></label><label>Tipo<select id="mp-team-type"><option value="propria">Própria</option><option value="terceirizada">Terceirizada</option></select></label><label>Membros (cadastros individuais)<select id="mp-team-members" multiple size="5"></select></label><button id="mp-team-save" type="button">Cadastrar equipe</button><label>Equipe para planejar<select id="mp-team"></select></label><button id="mp-team-plan" type="button">Planejar equipe no dia, obra e horas acima</button><label><input id="mp-period-ack" type="checkbox"> Conferi dias especiais e localidade dos dias selecionados.</label><button id="mp-team-period" type="button">Planejar equipe nos dias selecionados do período</button><h3>Indisponibilidade por intervalo</h3><p>Usa o funcionário selecionado no planejamento. Não lança falta ou férias na frequência.</p><label>Início<input id="mp-unavail-start" type="date"></label><label>Fim<input id="mp-unavail-end" type="date"></label><label>Motivo<select id="mp-unavail-reason"><option value="ferias">Férias</option><option value="folga">Folga</option><option value="atestado">Atestado</option><option value="afastamento">Afastamento</option><option value="falta">Falta conhecida</option></select></label><button id="mp-unavail-save" type="button">Registrar indisponibilidade</button><div id="mp-unavail-list"></div><h3>Calendário por localidade da obra</h3><p>Use a obra selecionada acima. Feriados são os cadastrados; não há consulta a calendário oficial. O cadastro legado de Passos só é aplicado a obras configuradas como Passos/MG.</p><label>Localidade da obra (ex.: Passos/MG)<input id="mp-location" maxlength="120"></label><button id="mp-location-save" type="button">Vincular localidade à obra</button><label>Data do feriado<input id="mp-holiday-day" type="date"></label><label>Nome do feriado<input id="mp-holiday-name" maxlength="120"></label><label>Abrangência<input id="mp-holiday-location" placeholder="Nacional ou localidade igual à da obra" maxlength="120"></label><button id="mp-holiday-save" type="button">Cadastrar feriado para conferência</button><h3>Replicar frequência realizada</h3><p>Origem: dia selecionado acima. Registros de destino existentes são preservados. Destinos futuros ficam bloqueados: use planejamento.</p><label>Datas de destino (separadas por vírgulas)<input id="mp-copy-days" placeholder="2026-11-03,2026-11-04"></label><button id="mp-copy-preview" type="button">Preparar conferência da réplica</button><div style="overflow:auto"><table><thead><tr><th>Confirmar</th><th>Data</th><th>Funcionário</th><th>Obras, horas e horários editáveis</th><th>Conferência</th></tr></thead><tbody id="mp-copy-rows"></tbody></table></div><label><input id="mp-copy-ack" type="checkbox"> Conferi domingos, feriados e localidades dos registros selecionados.</label><button id="mp-copy-confirm" type="button" disabled>Confirmar réplica selecionada</button><p id="mp-message" role="status"></p>`;$('mj-dialog').append(panel);
let preview=null,frequencySnapshot=null,configSnapshot=null;const people=()=>getColaboradoresDb(),state=()=>P.config(localStorage),passos=()=>typeof getFeriadosPassosDb==='function'?getFeriadosPassosDb():{},say=s=>$('mp-message').textContent=s;
const run=fn=>()=>{try{fn();}catch(e){say(e.message);}};const uid=()=>MartinsPersistenciaRdo.newId();
function refreshDay(){$('mj-day').dispatchEvent(new Event('change'));}
function saveConfig(next,expected){J.write(localStorage,P.KEY,next,expected);renderTeams();renderIntervals();refreshDay();}
function renderTeams(){const selected=$('mp-team').value;const c=state();$('mp-team').replaceChildren(new Option('Selecione',''));for(const t of c.teams.filter(x=>!x.cancelado))$('mp-team').add(new Option(t.nome+' · '+(t.tipo==='propria'?'Própria':'Terceirizada'),t.id));$('mp-team').value=selected;const chosen=new Set([...$('mp-team-members').selectedOptions].map(x=>x.value));$('mp-team-members').replaceChildren();for(const e of people().filter(x=>x.status!=='Inativo')){const o=new Option(e.nome,String(e.id));o.selected=chosen.has(String(e.id));$('mp-team-members').add(o);}}
function renderIntervals(){const c=state(),employees=people();$('mp-unavail-list').replaceChildren();for(const x of c.unavailability.filter(x=>!x.cancelado)){const p=document.createElement('p');p.textContent=(employees.find(e=>String(e.id)===x.funcionarioId)?.nome||x.funcionarioId)+' — '+x.motivo+' — '+MartinsFluxos.br(x.inicio)+' a '+MartinsFluxos.br(x.fim);const button=document.createElement('button');button.type='button';button.textContent='Encerrar restrição de planejamento';button.onclick=run(()=>{const before=localStorage.getItem(P.KEY),next=state(),entry=next.unavailability.find(e=>e.id===x.id);if(!entry||entry.cancelado)throw Error('Intervalo mudou; atualize');entry.cancelado=true;entry.encerradoEm=new Date().toISOString();saveConfig(next,before);say('Restrição encerrada, histórico preservado. Frequência não alterada.');});p.append(button);$('mp-unavail-list').append(p);}}
function renderPeriod(){const c=state(),work=$('mj-work').value,rows=J.read(localStorage,J.KEYS.plans,[]);$('mp-period-rows').replaceChildren();for(const day of P.period($('mj-day').value,$('mp-period').value)){const planned=rows.filter(x=>x.data===day),cal=P.calendar(day,work,c,passos()),tr=document.createElement('tr');const selectCell=document.createElement('td'),selectDay=document.createElement('input');selectDay.type='checkbox';selectDay.className='mp-period-select';selectDay.value=day;selectDay.setAttribute('aria-label','Planejar equipe em '+day);selectCell.append(selectDay);tr.append(selectCell);for(const text of [MartinsFluxos.br(day),[...cal.labels,...(cal.unconfigured?['Localidade não configurada']:[])].join('; ')||'Sem impedimento no calendário cadastrado',new Set(planned.map(x=>x.funcionarioId)).size,planned.reduce((s,x)=>s+Number(x.horas),0)]){const td=document.createElement('td');td.textContent=String(text);tr.append(td);}const td=document.createElement('td'),button=document.createElement('button');button.type='button';button.textContent='Abrir';button.onclick=run(()=>{$('mj-day').value=day;refreshDay();});td.append(button);tr.append(td);$('mp-period-rows').append(tr);}}
$('mp-team-save').onclick=run(()=>{const before=localStorage.getItem(P.KEY),members=[...$('mp-team-members').selectedOptions].map(x=>x.value),next=P.saveTeam(state(),{id:uid(),nome:$('mp-team-name').value,tipo:$('mp-team-type').value,membros:members},people());saveConfig(next,before);say('Equipe cadastrada; dados individuais e vínculo empregatício preservados.');});
$('mp-team-plan').onclick=run(()=>{const before=localStorage.getItem(J.KEYS.plans),next=P.planTeam(J.read(localStorage,J.KEYS.plans,[]),state(),$('mp-team').value,$('mj-work').value,$('mj-day').value,Number($('mj-hours').value),people(),getFrequenciaDiariaDb());J.write(localStorage,J.KEYS.plans,next,before);refreshDay();renderPeriod();say('Equipe planejada. Nenhuma presença foi registrada.');});
$('mp-team-period').onclick=run(()=>{const days=[...$('mp-period-rows').querySelectorAll('.mp-period-select:checked')].map(x=>x.value),before=localStorage.getItem(J.KEYS.plans),next=P.planTeamDays(J.read(localStorage,J.KEYS.plans,[]),state(),$('mp-team').value,$('mj-work').value,days,Number($('mj-hours').value),people(),getFrequenciaDiariaDb(),passos(),$('mp-period-ack').checked);J.write(localStorage,J.KEYS.plans,next,before);refreshDay();renderPeriod();say('Equipe planejada em '+days.length+' dia(s). Frequência permanece independente.');});
$('mp-unavail-save').onclick=run(()=>{const before=localStorage.getItem(P.KEY),next=P.addInterval(state(),{id:uid(),funcionarioId:$('mj-person').value,inicio:$('mp-unavail-start').value,fim:$('mp-unavail-end').value,motivo:$('mp-unavail-reason').value,criadoEm:new Date().toISOString()},people());saveConfig(next,before);say('Indisponibilidade registrada apenas no planejamento.');});
$('mp-location-save').onclick=run(()=>{const location=$('mp-location').value.trim(),work=$('mj-work').value;if(!location||!work)throw Error('Selecione obra e localidade');const before=localStorage.getItem(P.KEY),next=state();Object.defineProperty(next.workLocations,work,{value:location,writable:true,enumerable:true,configurable:true});saveConfig(next,before);renderPeriod();say('Localidade vinculada ao calendário da obra.');});
$('mp-holiday-save').onclick=run(()=>{const before=localStorage.getItem(P.KEY),next=P.addHoliday(state(),{id:uid(),data:$('mp-holiday-day').value,nome:$('mp-holiday-name').value,localidade:$('mp-holiday-location').value});saveConfig(next,before);renderPeriod();say('Feriado cadastrado para conferência, sem alterar frequências.');});
$('mp-view').onclick=run(renderPeriod);$('mp-period').onchange=run(renderPeriod);
function prepareCopy(){preview=null;$('mp-copy-confirm').disabled=true;$('mp-copy-rows').replaceChildren();const days=MartinsFluxos.dates($('mp-copy-days').value),freq=getFrequenciaDiariaDb();preview=P.previewCopy(freq,$('mj-day').value,days,people(),state(),new Date().toLocaleDateString('en-CA'),passos());frequencySnapshot=localStorage.getItem(J.KEYS.frequency);configSnapshot=localStorage.getItem(P.KEY);$('mp-copy-ack').checked=false;$('mp-copy-rows').replaceChildren();for(const row of preview.entries){const tr=document.createElement('tr');tr.dataset.key=row.key;const td=document.createElement('td'),check=document.createElement('input');check.type='checkbox';check.disabled=Boolean(row.issues.length);check.setAttribute('aria-label','Replicar '+row.nome+' em '+row.day);check.className='mp-copy-select';td.append(check);tr.append(td);for(const text of [MartinsFluxos.br(row.day),row.nome]){const cell=document.createElement('td');cell.textContent=text;tr.append(cell);}const hours=document.createElement('td');for(const a of row.allocations){const label=document.createElement('label');label.className='mp-copy-allocation';const work=document.createElement('select');work.className='mp-copy-work';const names=[...new Set([a.obra,...Object.keys(dadosObras)])];for(const name of names)work.add(new Option(name,name));work.value=a.obra;work.disabled=Boolean(row.issues.length);work.setAttribute('aria-label','Obra '+row.nome+' '+row.day);const input=document.createElement('input');input.type='number';input.min='0.25';input.max='8';input.step='0.25';input.value=a.horas;input.className='mp-copy-hours';input.setAttribute('aria-label','Horas '+row.nome+' '+a.obra+' '+row.day);input.disabled=Boolean(row.issues.length);work.onchange=()=>{$('mp-copy-ack').checked=false;const warnings=[...tr.querySelectorAll('.mp-copy-work')].flatMap(x=>{const c=P.calendar(row.day,x.value,state(),passos());return [...c.labels,...(c.unconfigured?['Localidade não configurada']:[])];});tr.lastElementChild.textContent=[...row.issues,...new Set(warnings)].join('; ')||'Disponível para conferência';};label.append(work,input);hours.append(label);}for(const [field,text] of [['entrada','Entrada'],['saida','Saída']]){const label=document.createElement('label');label.textContent=text+' ';const input=document.createElement('input');input.type='time';input.className='mp-copy-'+field;input.value=row[field];input.setAttribute('aria-label',text+' '+row.nome+' '+row.day);input.disabled=Boolean(row.issues.length);label.append(input);hours.append(label);}tr.append(hours);const result=document.createElement('td');result.textContent=[...row.issues,...row.warnings].join('; ')||'Disponível para conferência';tr.append(result);$('mp-copy-rows').append(tr);}$('mp-copy-confirm').disabled=!preview.entries.some(x=>!x.issues.length);say(preview.entries.length?preview.entries.length+' registro(s) preparado(s). Nenhuma frequência foi gravada.':'O dia de origem não possui presenças. Escolha um dia com frequência realizada para preparar a réplica.');}
$('mp-copy-preview').onclick=run(prepareCopy);
$('mp-copy-confirm').onclick=run(()=>{if(!preview)throw Error('Prepare a conferência');if(localStorage.getItem(P.KEY)!==configSnapshot)throw Error('Disponibilidade ou calendário mudou; prepare a conferência novamente');const selections=[...$('mp-copy-rows').children].filter(tr=>tr.querySelector('.mp-copy-select').checked).map(tr=>({key:tr.dataset.key,allocations:[...tr.querySelectorAll('.mp-copy-allocation')].map(x=>({obra:x.querySelector('.mp-copy-work').value,horas:Number(x.querySelector('.mp-copy-hours').value)})),entrada:tr.querySelector('.mp-copy-entrada').value,saida:tr.querySelector('.mp-copy-saida').value}));const next=P.confirmCopy(getFrequenciaDiariaDb(),preview,selections,people(),state(),new Date().toLocaleDateString('en-CA'),passos(),$('mp-copy-ack').checked,Object.keys(dadosObras));J.write(localStorage,J.KEYS.frequency,next,frequencySnapshot);preview=null;$('mp-copy-confirm').disabled=true;refreshDay();renderAuditoriaPonto();say(selections.length+' registro(s) replicado(s) após conferência. Destinos existentes preservados.');});
panel.addEventListener('toggle',()=>{if(panel.open){try{renderTeams();renderIntervals();renderPeriod();}catch(e){say(e.message);}}});$('mj-day').addEventListener('change',()=>{if(panel.open){try{renderPeriod();}catch(e){say(e.message);}}});
window.prepararReplicaFrequencia=(source,destination)=>{try{$('mj-day').value=source;if(!$('mj-dialog').open)$('mj-dialog').showModal();refreshDay();panel.open=true;$('mp-copy-days').value=destination;renderTeams();renderIntervals();renderPeriod();prepareCopy();$('mp-copy-rows').scrollIntoView({block:'center'});}catch(e){say(e.message);}};
})();
